style.css:
@-moz-document domain("google.com") {
/* MAIN BACKGROUND */
html,
body {
    background: #fff0f5 !important;
    background-color: #fff0f5 !important;
}

/* MAIN PAGE AREAS */
#viewport,
#main,
#searchform,
#cnt,
#appbar,
#sfooter {
    background-color: #fff0f5 !important;
}

/* GOOGLE LOGO */
img[alt="Google"],
img.lnXdpd,
#hplogo {
    filter: sepia(1) saturate(3) hue-rotate(285deg) !important;
}

/* SEARCH BAR */
.RNNXgb {
    background: #ffe0eb !important;
    border: 2px solid #f4b6cc !important;
    border-radius: 30px !important;
    box-shadow: none !important;
}

.RNNXgb:hover,
.RNNXgb:focus-within {
    background: #fff5f8 !important;
    border-color: #e99bb8 !important;
    box-shadow: 0 1px 6px #e8b5c8 !important;
}

/* SEARCH INPUT */
textarea[name="q"],
input[name="q"] {
    color: #75445a !important;
    caret-color: #d979a0 !important;
}

/* SEARCH ICONS */
.RNNXgb svg {
    fill: #d98ba9 !important;
    color: #d98ba9 !important;
}

/* SEARCH BUTTONS */
input[type="submit"],
button,
.GN5eCb {
    background-color: #f8c6d8 !important;
    color: #814c63 !important;
    border-color: #efb1c8 !important;
    border-radius: 20px !important;
}

input[type="submit"]:hover,
button:hover {
    background-color: #f3b1ca !important;
}

/* TOP NAVIGATION */
a {
    color: #bd7092 !important;
}

a:hover {
    color: #e18bab !important;
}

/* GOOGLE APPS ICON */
.gb_d,
.gb_A,
header svg {
    color: #d98ba9 !important;
    fill: #d98ba9 !important;
}

/* FOOTER */
#fbar,
#footer,
#sfooter {
    background: #fbdce7 !important;
    border-color: #f3bfd1 !important;
}

#fbar a,
#footer a,
#sfooter a {
    color: #b66c8c !important;
}

/* TEXT COLORS */
h1, h2, h3, label {
    color: #a85e7e !important;
}

/* SELECTION COLOR */
::selection {
    background: #f3b6ce !important;
    color: #75445a !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #fff0f5;
}

::-webkit-scrollbar-thumb {
    background: #efb1c8;
    border-radius: 10px;
}
}
